function conferir(sistema, planilha) {
  const a = new Set(sistema)
  const b = new Set(planilha)

  const emAmbos = [...a].filter((codigo) => b.has(codigo)).sort()
  const soNoSistema = [...a].filter((codigo) => !b.has(codigo)).sort()
  const soNaPlanilha = [...b].filter((codigo) => !a.has(codigo)).sort()

  return { emAmbos, soNoSistema, soNaPlanilha }
}

function estimar(entrada) {
  const numero = (valor) => (Number.isFinite(valor) ? Math.max(0, valor) : 0)

  const usuarios = numero(entrada?.usuariosPorDia)
  const acoes = numero(entrada?.acoesPorUsuario)
  const bytes = numero(entrada?.bytesPorRegistro)
  const dias = numero(entrada?.dias)

  const registrosPorDia = usuarios * acoes
  const registrosNoPeriodo = registrosPorDia * dias
  const gigabytes = Math.round(((registrosNoPeriodo * bytes) / 1e9) * 10) / 10

  return { registrosPorDia, registrosNoPeriodo, gigabytes }
}

function chanceDeSucesso(taxaDeFalha, tentativas) {
  if (!Number.isFinite(taxaDeFalha) || taxaDeFalha < 0 || taxaDeFalha > 1) return null
  if (!Number.isFinite(tentativas) || tentativas <= 0) return 0

  const falhaEmTodas = taxaDeFalha ** tentativas
  return Math.round((1 - falhaEmTodas) * 10000) / 10000
}

