function podeReabrir(ticket, usuario) {
  // A exceção ignora as duas condições, então ela decide antes.
  if (usuario.papel === 'suporte') return true

  // Versão positiva da regra negativa: mais fácil de ler e de revisar.
  return ticket.fechado === true && ticket.diasDesdeFechamento <= 30
}
